import{_ as l,l as n,o as e,c as d,v as r,p as s,x as o,d as i,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"word RAM 与位并行","description":"","frontmatter":{"title":"word RAM 与位并行","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/word-ram.md","filePath":"cs/word-ram.md","lastUpdated":1789023840000}'),c={name:"cs/word-ram.md"};function m(w,a,A,_,u,f){const t=n("Mermaid");return e(),d("div",null,[a[1]||(a[1]=r('<h1 id="word-ram-与位并行" tabindex="-1">word RAM 与位并行 <a class="header-anchor" href="#word-ram-与位并行" aria-label="Permalink to &quot;word RAM 与位并行&quot;">​</a></h1><div class="epigraph"><p>字长 $w=\\Theta(\\log n)$ 时，一次字运算处理 $w$ 比特；排序、选择、编辑距离都能比比较模型更快。</p><footer>—— 据 Fredman and Willard；Hagerup 字模型综述；Myers 位并行；[序列比对](/cs/sequence-alignment) 整理</footer></div><p>上一课<a href="/cs/adversary-argument">对手论证</a>钉死比较模型下界。word RAM：内存字 \\(w\\) 位，加减与位运算 \\(O(1)\\)。缺口是这个模型如何<strong>绕开</strong> \\(\\Omega(n\\log n)\\)：基数排序、融合树、位集。算法进阶课程在此收束。不重写 Myers 细节。不写 Transformer、不进限价簿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>比较模型每问 1 比特。word RAM 一次可读 \\(w\\) 个键的高位或做掩码。整数排序：\\(O(n\\log\\log n)\\) 等（Thorup 等，点名）。位图集合运算 \\(O(n/w)\\)。Myers 编辑距离 \\(O(nm/w)\\) 已见。popcount、前导零是硬件原语。</p><p>缺口是模型，不是再证比较下界无效——下界换模型即失效。</p><h3 id="太小或太大都不自然" tabindex="-1">\\(w\\) 太小或太大都不自然 <a class="header-anchor" href="#太小或太大都不自然" aria-label="Permalink to &quot;$w$ 太小或太大都不自然&quot;">​</a></h3><p>\\(w=\\Theta(\\log n)\\) 可当地址。\\(w=n\\) 则一次运算过大，模型作弊。转位表、四俄国人法是 \\(w\\) 与块的折中。</p><p><span class="marginnote">Fredman–Willard 融合树。Hagerup 综述。本课程从 SCC 到 word RAM：图、代数、DP、串、几何、随机近似、最后模型。后课若有附录不插入主干。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把状态打进字：状压 DP 的一行、NFA 位集、网格位图。注意移位方向与字边界。复杂度写 \\(O(n/w)\\) 时声明 \\(w\\)。</p>',11)),(e(),s(h,null,{default:o(()=>[p(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CMP%5B%22%E6%AF%94%E8%BE%83%E6%A8%A1%E5%9E%8B%20%CE%A9(n%20log%20n)%22%5D%20--%3E%20WRAM%5B%22word%20RAM%20w%20%E4%BD%8D%22%5D%0A%20%20WRAM%20--%3E%20FAST%5B%22%E4%BD%8D%E5%B9%B6%E8%A1%8C%20%2F%20%E5%9F%BA%E6%95%B0%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>转回比较模型须显式模拟代价。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>信息论下界按比特，字运算一次买 \\(w\\) 比特。与 NTT：字里的模乘仍是一次。与 PRAM：并行是多核；位并行是核内 SIMD/字。与几何谓词：字 RAM 不自动给精确实数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写融合树全证明。不写电路深度。算法进阶封口：后课默认会选模型——比较、RAM、word RAM、I/O、PRAM、流、在线。下一课程从 <a href="/cs/lex-flex">lex / flex</a> 起编译器生成器。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>word RAM 一次 \\(w\\) 比特，可破比较下界。</li><li>位并行、基数、融合树是实例。</li><li>\\(w=\\Theta(\\log n)\\) 才诚实。</li><li>出处：Fredman and Willard；Myers, 1999；Knuth 位技巧。</li></ul>',7))])}const g=l(c,[["render",m]]);export{T as __pageData,g as default};
